\[
f(a, b)=\frac{a^{4}}{b^{4}}+\frac{b^{4}}{a^{4}}-\frac{a^{2}}{b^{2}}-\frac{b^{2}}{a^{2}}+\frac{a}{b}+\frac{b}{a}
\]

